package com.afirma.assina;
import java.util.*;
import java.net.*;
import java.net.http.*;
import java.nio.charset.StandardCharsets;
import java.time.Duration;
import org.springframework.stereotype.Service;
import org.springframework.core.env.Environment;
import org.springframework.http.HttpStatus;
import org.springframework.web.server.ResponseStatusException;
import tools.jackson.databind.ObjectMapper;
import tools.jackson.databind.JsonNode;

/** Contratos SGA, Asaas e hControl da origem. Nenhuma credencial da origem é copiada. */
@Service
public class IntegracoesAutentica {
 private final BancoAssineai banco;private final ObjectMapper json;private final Environment ambiente;
 private final HttpClient http=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(5)).followRedirects(HttpClient.Redirect.NEVER).build();
 public IntegracoesAutentica(BancoAssineai banco,ObjectMapper json,Environment ambiente){this.banco=banco;this.json=json;this.ambiente=ambiente;}
 private String token(long cliente,String integracao){var r=banco.um("SELECT \"IntegracaoDados\" FROM autentica.\"Integracao\" WHERE \"ClienteId\"=:c AND lower(\"IntegracaoNome\")=lower(:nome) AND \"IntegracaoStatus\" ORDER BY id LIMIT 1",Map.of("c",cliente,"nome",integracao));if(r==null)throw new ResponseStatusException(HttpStatus.CONFLICT,"Integração não configurada ou desativada");Object d=r.get("IntegracaoDados"),valor=null;if(d instanceof Map<?,?> m)valor=m.get("Token");if(d instanceof List<?> l)for(Object v:l)if(v instanceof Map<?,?> m&&"Token".equals(m.get("campo")))valor=m.get("valor");if(integracao.equalsIgnoreCase("hControl")){
  String clientId=parametro(d,"clientId"),secretId=parametro(d,"secretId");
  if(!clientId.isBlank()&&!secretId.isBlank()){String recebido=chamar("HCONTROL_BASE_URL","/Account/Token?"+query(Map.of("clientId",clientId,"secretId",secretId)),"GET",Map.of(),null).path("data").path("token").asText();if(!recebido.isBlank())return recebido;}
 }
 String t=Objects.toString(valor,"");if(t.startsWith("APP_INTEGRACAO_"))t=Objects.toString(ambiente.getProperty(t),"");if(t.isBlank())throw new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE,"Token da integração não configurado");return t;}
 private String parametro(Object dados,String campo){Object valor=null;if(dados instanceof Map<?,?> m)valor=m.get(campo);if(dados instanceof List<?> lista)for(Object v:lista)if(v instanceof Map<?,?> m&&campo.equals(m.get("campo")))valor=m.get("valor");String t=Objects.toString(valor,"");return t.startsWith("APP_INTEGRACAO_")?ambiente.getProperty(t,""):t;}
 private String query(Map<String,Object> filtros){var partes=new ArrayList<String>();for(var e:filtros.entrySet())if(e.getValue()!=null)partes.add(URLEncoder.encode(e.getKey(),StandardCharsets.UTF_8)+"="+URLEncoder.encode(e.getValue().toString(),StandardCharsets.UTF_8));return String.join("&",partes);}
 JsonNode chamar(String base,String caminho,String metodo,Map<String,String> headers,Object corpo){String url=Objects.toString(ambiente.getProperty(base),"");if(url.isBlank())throw new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE,"Configure "+base);String destino=url.replaceAll("/$","")+caminho;URI endereco=URI.create(destino);RegrasAutentica.exigir(Set.of("https","http").contains(endereco.getScheme())&&endereco.getHost()!=null&&endereco.getUserInfo()==null,"Base de integração inválida");try{var req=HttpRequest.newBuilder(URI.create(destino)).timeout(Duration.ofSeconds(30)).header("Accept","application/json");headers.forEach(req::header);if(corpo!=null)req.header("Content-Type","application/json");req.method(metodo,corpo==null?HttpRequest.BodyPublishers.noBody():HttpRequest.BodyPublishers.ofString(json.writeValueAsString(corpo)));var r=http.send(req.build(),HttpResponse.BodyHandlers.ofInputStream());try(var in=r.body()){byte[] bytes=in.readNBytes(5*1024*1024+1);if(r.statusCode()<200||r.statusCode()>=300){if(base.equals("SGA_BASE_URL")&&new String(bytes,StandardCharsets.UTF_8).contains("Não foram encontrados boletos dentro dos parâmetros enviados"))return json.createArrayNode();throw new ResponseStatusException(HttpStatus.BAD_GATEWAY,"A integração recusou a operação (HTTP "+r.statusCode()+")");}if(bytes.length>5*1024*1024)throw new ResponseStatusException(HttpStatus.BAD_GATEWAY,"Resposta da integração muito grande");return bytes.length==0?json.createObjectNode():json.readTree(bytes);}}catch(ResponseStatusException e){throw e;}catch(Exception e){if(e instanceof InterruptedException)Thread.currentThread().interrupt();throw new ResponseStatusException(HttpStatus.BAD_GATEWAY,"Integração indisponível");}}
 public Object consultar(long cliente,String nome,String operacao,Map<String,Object> filtros){
  String t=token(cliente,nome);var f=new HashMap<>(filtros);RegrasAutentica.exigir(f.size()<=40,"Muitos filtros");
  if(nome.equalsIgnoreCase("Asaas")){String caminho=switch(operacao){case "cobrancas"->"/payments";case "clientes"->"/customers";default->throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Operação inválida");};var lista=json.createArrayNode();int offset=0;for(int pagina=0;pagina<100;pagina++){f.put("offset",offset);f.put("limit",100);var r=chamar("ASAAS_BASE_URL",caminho+"?"+query(f),"GET",Map.of("access_token",t),null);if(r.path("data").isArray())r.path("data").forEach(lista::add);if(!r.path("hasMore").asBoolean())return lista;int tamanho=r.path("data").size();RegrasAutentica.exigir(tamanho>0,"Paginação inválida na integração");offset+=tamanho;}throw new ResponseStatusException(HttpStatus.BAD_GATEWAY,"Refine os filtros; resultado maior que 10 mil registros");}
  if(nome.equalsIgnoreCase("SGA")){if(operacao.equals("situacoes"))return chamar("SGA_BASE_URL","/listar/situacao-boleto/ativo","GET",Map.of("Authorization","Bearer "+t),null);RegrasAutentica.exigir(operacao.equals("boletos"),"Operação inválida");var lista=json.createArrayNode();for(int pagina=0;pagina<100;pagina++){f.put("inicio_paginacao",pagina);f.put("quantidade_por_pagina",1000);var r=chamar("SGA_BASE_URL","/listar/boleto/periodo","POST",Map.of("Authorization","Bearer "+t),f);RegrasAutentica.exigir(r.isArray(),"Resposta inválida do SGA");r.forEach(lista::add);if(r.size()==0)return lista;}throw new ResponseStatusException(HttpStatus.BAD_GATEWAY,"Refine os filtros do SGA");}
  if(nome.equalsIgnoreCase("hControl")){String caminho=switch(operacao){case "boletos"->f.containsKey("cpfCnpj")||f.containsKey("cpfCnpjCliente")?"/Financeiro/ObterBoletosEmAbertoPorCpfCnpj":"/Financeiro/ObterBoletosEmAberto";case "imprimir"->"/Financeiro/ImprimirBoleto";case "clientes"->"/ObterClientes";default->throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Operação inválida");};if(f.containsKey("cpfCnpj"))f.put("cpfCnpjCliente",f.remove("cpfCnpj").toString().replaceAll("[^0-9]",""));return chamar("HCONTROL_BASE_URL",caminho+"?"+query(f),operacao.equals("imprimir")?"POST":"GET",Map.of("Authorization","Bearer "+t),null).path("data");}
  throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Integração desconhecida");
 }
 public Object boletosBot(long empresa,String cpf,String clientId,String secretId){RegrasAutentica.exigir(cpf.replaceAll("[^0-9]","").matches("[0-9]{11}|[0-9]{14}"),"Informe CPF ou CNPJ válido");var chave=chamar("HCONTROL_BASE_URL","/Account/Token?"+query(Map.of("clientId",clientId,"secretId",secretId)),"GET",Map.of(),null).path("data").path("token").asText();if(chave.isBlank())throw new ResponseStatusException(HttpStatus.BAD_GATEWAY,"hControl não confirmou a autenticação");return chamar("HCONTROL_BASE_URL","/Financeiro/ObterBoletosEmAbertoPorCpfCnpj?"+query(Map.of("cpfCnpjCliente",cpf.replaceAll("[^0-9]",""))),"GET",Map.of("Authorization","Bearer "+chave),null).path("data");}
}
